def minPath(grid, k):
    from collections import deque

    n = len(grid)
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # Create a mapping of values to their positions
    value_to_position = {}
    for i in range(n):
        for j in range(n):
            value_to_position[grid[i][j]] = (i, j)

    # To store the result path
    min_path = []

    # BFS to explore all paths of length k
    def bfs(start_value):
        queue = deque([(start_value, [start_value])])
        best_path = None

        while queue:
            current_value, path = queue.popleft()
            if len(path) == k:
                if best_path is None or path < best_path:
                    best_path = path
                continue

            if len(path) < k:
                x, y = value_to_position[current_value]
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < n:
                        next_value = grid[nx][ny]
                        queue.append((next_value, path + [next_value]))

        return best_path

    # Start BFS from each cell in the grid
    for value in range(1, n * n + 1):
        path = bfs(value)
        if path:
            if not min_path or path < min_path:
                min_path = path

    return min_path

